-- challenge chal_quiz_devf_111 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_devf_111', (SELECT id FROM catalog.course WHERE public_id = 'devops-foundations-ci-containers'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'devops-foundations-ci-containers') AND order_index = 1 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-devf-1-1' AND is_deleted = false LIMIT 1), 'exit-codes-signals-pipefail-quiz', 'Exit codes, signals and pipefail', 'Read a short bash script and a container that will not stop the way the shell and the kernel see them: which exit status wins, and what 137 really tells you.', 'open', 'easy'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_devf_111'), 'This script runs with bash 5 in a folder where missing.txt does not exist. What happens?

#!/usr/bin/env bash
set -e
false | true
echo "after pipe: $?"
grep -q needle missing.txt
echo "done"', 'single_choice'::question_type, 'Without pipefail, the status of a pipeline is the status of its last command. false | true ends with true, so the status is 0: set -e does not stop the script and echo prints "after pipe: 0". grep then cannot open missing.txt: it prints an error on stderr and exits with 2 (grep uses 0 for a match, 1 for no match and 2 for an error). set -e stops the script there, so "done" is never printed and the script''s exit code is 2. Stopping at false | true would need set -o pipefail. "after pipe: 1" would be printed only if the pipeline status were the first command''s. Printing "done" and exiting 0 ignores set -e. Exiting with 1 confuses grep''s "no match" status with its error status.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_devf_111') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('The script stops at false | true with exit code 1 and prints nothing.', false),
        ('It prints "after pipe: 0", grep prints an error, and the script stops with exit code 2.', true),
        ('It prints "after pipe: 1", grep prints an error, and the script stops with exit code 2.', false),
        ('It prints "after pipe: 0", grep prints an error, then "done", and the script exits with 0.', false),
        ('It prints "after pipe: 0" and stops with exit code 1, because grep found no match.', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_devf_111'), 'Rice Rocket''s api image has CMD ["./start.sh"], and start.sh runs `python manage.py migrate` and then `gunicorn api:app --bind 0.0.0.0:8000` (no exec). Every `docker stop` takes about 10 seconds and docker ps -a shows Exited (137). Which statements are true? (Select all that apply.)', 'multiple_choice'::question_type, '137 is 128 + 9: the main process was killed by signal 9, SIGKILL. docker stop first sends SIGTERM (the image''s STOPSIGNAL) to PID 1, waits for the grace period (10 seconds by default, -t / --timeout changes it) and then sends SIGKILL. Here PID 1 is the shell running start.sh: a process that is PID 1 in its namespace ignores signals it has no handler for, and the shell does not pass SIGTERM on to gunicorn, so nothing happens until SIGKILL. exec gunicorn ... replaces the shell with gunicorn, which becomes PID 1, receives SIGTERM itself and shuts down gracefully. 137 does not always mean out of memory: the kernel''s OOM killer also uses SIGKILL, so check docker inspect (State.OOMKilled) before blaming memory. kill -9 (SIGKILL) cannot be caught, blocked or trapped, so no trap or cleanup handler runs.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_devf_111') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('137 is 128 + 9: the container''s main process was killed by SIGKILL.', true),
        ('docker stop sends SIGTERM, waits for a grace period (10 seconds by default), then sends SIGKILL.', true),
        ('Exit code 137 always means that the container ran out of memory.', false),
        ('Changing the last line of start.sh to exec gunicorn api:app --bind 0.0.0.0:8000 makes gunicorn PID 1, so it receives SIGTERM itself.', true),
        ('kill -9 gives the process a chance to run its trap or signal handlers before it exits.', false)
    ) AS o(option_text, is_correct);

