INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_devf_112', (SELECT id FROM catalog.course WHERE public_id = 'devops-foundations-ci-containers'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'devops-foundations-ci-containers') AND order_index = 1 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-devf-1-1' AND is_deleted = false LIMIT 1), 'explain-ci-job-exit-codes', 'Explain a CI job''s exit codes', 'The deploy job went green while the migration failed, and the next deploy died with 137. Write a small tool for the on-call: pipeline_status(codes, pipefail) returns a pipeline''s exit status the way bash does (last command, or the rightmost failure with pipefail), meaning(code) explains an exit code (ok, command not found, killed by SIGTERM, error (exit 3) ...), and run_job(steps, pipefail) runs the steps like set -e: it stops at the first failing step, marks the rest as skipped and reports the job result and exit code. The test runner reads the job from stdin and prints the report as JSON.', 'open', 'easy'::difficulty_question, 'mini_coding', 30, true, false)
