INSERT INTO challenge.challenge_test_cases (challenge_id, name, input_data, expected_output, score, is_sample, is_hidden, sort_order)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_devf_112'), 'The incident: migrate.sh | tee without pipefail looks green', '{"pipefail":false,"steps":[{"name":"install","pipeline":[0]},{"name":"migrate","pipeline":[1,0]},{"name":"smoke-test","pipeline":[0]}]}', '{"steps":[{"name":"install","status":0,"meaning":"ok","commands":["ok"]},{"name":"migrate","status":0,"meaning":"ok","commands":["error (exit 1)","ok"]},{"name":"smoke-test","status":0,"meaning":"ok","commands":["ok"]}],"job":"ok","exit_code":0}', 5, true, false, 1),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_devf_112'), 'Same job with pipefail: the migration failure stops the job', '{"pipefail":true,"steps":[{"name":"install","pipeline":[0]},{"name":"migrate","pipeline":[1,0]},{"name":"smoke-test","pipeline":[0]}]}', '{"steps":[{"name":"install","status":0,"meaning":"ok","commands":["ok"]},{"name":"migrate","status":1,"meaning":"error (exit 1)","commands":["error (exit 1)","ok"]},{"name":"smoke-test","status":null,"meaning":"skipped","commands":null}],"job":"failed at migrate (exit 1)","exit_code":1}', 5, true, false, 2),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_devf_112'), 'A deploy killed after the stop timeout exits 137 (SIGKILL)', '{"pipefail":true,"steps":[{"name":"build","pipeline":[0]},{"name":"deploy","pipeline":[137]},{"name":"notify","pipeline":[0,0]}]}', '{"steps":[{"name":"build","status":0,"meaning":"ok","commands":["ok"]},{"name":"deploy","status":137,"meaning":"killed by SIGKILL","commands":["killed by SIGKILL"]},{"name":"notify","status":null,"meaning":"skipped","commands":null}],"job":"failed at deploy (exit 137)","exit_code":137}', 5, true, false, 3),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_devf_112'), 'A typo in a script name: exit 127 in the last command', '{"pipefail":false,"steps":[{"name":"setup","pipeline":[0]},{"name":"seed","pipeline":[0,127]},{"name":"test","pipeline":[0]}]}', '{"steps":[{"name":"setup","status":0,"meaning":"ok","commands":["ok"]},{"name":"seed","status":127,"meaning":"command not found","commands":["ok","command not found"]},{"name":"test","status":null,"meaning":"skipped","commands":null}],"job":"failed at seed (exit 127)","exit_code":127}', 5, true, false, 4),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_devf_112'), 'pipefail takes the rightmost failing command, not the first', '{"pipefail":true,"steps":[{"name":"lint","pipeline":[0,0]},{"name":"test","pipeline":[3,1,0]},{"name":"package","pipeline":[0]},{"name":"upload","pipeline":[0]}]}', '{"steps":[{"name":"lint","status":0,"meaning":"ok","commands":["ok","ok"]},{"name":"test","status":1,"meaning":"error (exit 1)","commands":["error (exit 3)","error (exit 1)","ok"]},{"name":"package","status":null,"meaning":"skipped","commands":null},{"name":"upload","status":null,"meaning":"skipped","commands":null}],"job":"failed at test (exit 1)","exit_code":1}', 5, false, true, 5),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_devf_112'), 'Signals not in the SIGNALS table, SIGPIPE, exit 255 and 126 in one report', '{"pipefail":false,"steps":[{"name":"export","pipeline":[141,0]},{"name":"report","pipeline":[255,138,0]},{"name":"prepare","pipeline":[0,126]},{"name":"publish","pipeline":[0]}]}', '{"steps":[{"name":"export","status":0,"meaning":"ok","commands":["killed by SIGPIPE","ok"]},{"name":"report","status":0,"meaning":"ok","commands":["error (exit 255)","killed by signal 10","ok"]},{"name":"prepare","status":126,"meaning":"found but not executable","commands":["ok","found but not executable"]},{"name":"publish","status":null,"meaning":"skipped","commands":null}],"job":"failed at prepare (exit 126)","exit_code":126}', 5, false, true, 6);
