VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_devf_121'), 'The outage: lowercase level=error and a traceback that belongs to it', '{"min_level":"ERROR","lines":["2026-10-22T08:13:58Z level=info service=api msg=\"GET /orders/8812 200\" request_id=r-7a1","2026-10-22T08:14:01Z level=warn service=checkout msg=\"payment provider slow\" latency_ms=2950 request_id=r-7a2","2026-10-22T08:14:03Z level=error service=checkout msg=\"payment timeout\" request_id=r-7a2","  Traceback (most recent call last):","    File \"/app/checkout/pay.py\", line 41, in charge","      resp = client.post(url, json=body, timeout=3)","  TimeoutError: timed out","2026-10-22T08:14:04Z level=info service=api msg=\"GET /health 200\""]}', '{"total":4,"unparsed":0,"by_level":{"INFO":2,"WARN":1,"ERROR":1},"matches":[{"time":"2026-10-22T08:14:03Z","level":"ERROR","service":"checkout","msg":"payment timeout","extra_lines":4}]}', 5, true, false, 1),
