       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_fix_devf_212'), 'requirements.txt copied first: a code change reuses the pip layer', '{"previous":{"dockerfile":["FROM python:3.13-slim","WORKDIR /app","COPY requirements.txt .","RUN pip install --no-cache-dir -r requirements.txt","COPY . .","CMD [\"python\", \"-m\", \"api\"]"],"files":{"requirements.txt":"r1","app/main.py":"m1","app/routes.py":"t1","README.md":"d1",".git/HEAD":"g1","tests/test_routes.py":"x1"}},"current":{"dockerfile":["FROM python:3.13-slim","WORKDIR /app","COPY requirements.txt .","RUN pip install --no-cache-dir -r requirements.txt","COPY . .","CMD [\"python\", \"-m\", \"api\"]"],"files":{"requirements.txt":"r1","app/main.py":"m1","app/routes.py":"t2","README.md":"d1",".git/HEAD":"g1","tests/test_routes.py":"x1"}},"dockerignore":[".git","*.md","tests"],"seconds":[3,1,1,240,1,1]}', '{"steps":["CACHED FROM python:3.13-slim","CACHED WORKDIR /app","CACHED COPY requirements.txt .","CACHED RUN pip install --no-cache-dir -r requirements.txt","BUILD COPY . .","BUILD CMD [\"python\", \"-m\", \"api\"]"],"rebuilt":2,"build_seconds":2}', 4, true, false, 2),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_fix_devf_212'), 'README.md and .git change, both in .dockerignore: everything is cached', '{"previous":{"dockerfile":["FROM python:3.13-slim","WORKDIR /app","COPY requirements.txt .","RUN pip install --no-cache-dir -r requirements.txt","COPY . .","CMD [\"python\", \"-m\", \"api\"]"],"files":{"requirements.txt":"r1","app/main.py":"m1","app/routes.py":"t1","README.md":"d1",".git/HEAD":"g1","tests/test_routes.py":"x1"}},"current":{"dockerfile":["FROM python:3.13-slim","WORKDIR /app","COPY requirements.txt .","RUN pip install --no-cache-dir -r requirements.txt","COPY . .","CMD [\"python\", \"-m\", \"api\"]"],"files":{"requirements.txt":"r1","app/main.py":"m1","app/routes.py":"t1","README.md":"d2",".git/HEAD":"g2","tests/test_routes.py":"x1"}},"dockerignore":[".git","*.md","tests"],"seconds":[3,1,1,240,1,1]}', '{"steps":["CACHED FROM python:3.13-slim","CACHED WORKDIR /app","CACHED COPY requirements.txt .","CACHED RUN pip install --no-cache-dir -r requirements.txt","CACHED COPY . .","CACHED CMD [\"python\", \"-m\", \"api\"]"],"rebuilt":0,"build_seconds":0}', 4, true, false, 3),
