VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_devf_312'), 'Example: lint and unit in parallel, then build, then deploy', '{"jobs":[{"name":"lint","needs":[],"minutes":2,"result":"success"},{"name":"unit","needs":[],"minutes":5,"result":"success"},{"name":"build","needs":["lint","unit"],"minutes":3,"result":"success"},{"name":"deploy","needs":["build"],"minutes":2,"result":"success"}]}', '{"jobs":[{"name":"lint","status":"success","start":0,"end":2},{"name":"unit","status":"success","start":0,"end":5},{"name":"build","status":"success","start":5,"end":8},{"name":"deploy","status":"success","start":8,"end":10}],"wall_minutes":10,"critical_path":["unit","build","deploy"]}', 5, true, false, 1),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_devf_312'), 'An image scan after the build, not the long integration job, decides the wall time', '{"jobs":[{"name":"checkout-deps","needs":[],"minutes":1,"result":"success"},{"name":"lint","needs":["checkout-deps"],"minutes":2,"result":"success"},{"name":"unit","needs":["checkout-deps"],"minutes":6,"result":"success"},{"name":"integration","needs":["checkout-deps"],"minutes":9,"result":"success"},{"name":"build-image","needs":["lint","unit"],"minutes":4,"result":"success"},{"name":"scan-image","needs":["build-image"],"minutes":3,"result":"success"},{"name":"deploy-staging","needs":["build-image","integration"],"minutes":2,"result":"success"}]}', '{"jobs":[{"name":"checkout-deps","status":"success","start":0,"end":1},{"name":"lint","status":"success","start":1,"end":3},{"name":"unit","status":"success","start":1,"end":7},{"name":"integration","status":"success","start":1,"end":10},{"name":"build-image","status":"success","start":7,"end":11},{"name":"scan-image","status":"success","start":11,"end":14},{"name":"deploy-staging","status":"success","start":11,"end":13}],"wall_minutes":14,"critical_path":["checkout-deps","unit","build-image","scan-image"]}', 5, true, false, 2),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_devf_312'), 'A failed test skips build and, through it, deploy', '{"jobs":[{"name":"lint","needs":[],"minutes":2,"result":"success"},{"name":"unit","needs":[],"minutes":5,"result":"failure"},{"name":"build","needs":["lint","unit"],"minutes":3,"result":"success"},{"name":"deploy","needs":["build"],"minutes":2,"result":"success"},{"name":"docs","needs":["lint"],"minutes":4,"result":"success"}]}', '{"jobs":[{"name":"lint","status":"success","start":0,"end":2},{"name":"unit","status":"failure","start":0,"end":5},{"name":"build","status":"skipped","start":null,"end":null},{"name":"deploy","status":"skipped","start":null,"end":null},{"name":"docs","status":"success","start":2,"end":6}],"wall_minutes":6,"critical_path":["lint","docs"]}', 5, true, false, 3),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_devf_312'), 'A need with a typo is reported before anything is planned', '{"jobs":[{"name":"lint","needs":[],"minutes":2,"result":"success"},{"name":"test","needs":["lint"],"minutes":5,"result":"success"},{"name":"build","needs":["test"],"minutes":3,"result":"success"},{"name":"deploy","needs":["build","tests"],"minutes":2,"result":"success"}]}', '{"error":"job ''deploy'' needs unknown job ''tests''"}', 5, false, true, 4),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_devf_312'), 'Jobs in a cycle and the job waiting on them can never start', '{"jobs":[{"name":"lint","needs":[],"minutes":2,"result":"success"},{"name":"build","needs":["test"],"minutes":3,"result":"success"},{"name":"test","needs":["build","lint"],"minutes":5,"result":"success"},{"name":"deploy","needs":["build"],"minutes":2,"result":"success"},{"name":"docs","needs":["lint"],"minutes":1,"result":"success"}]}', '{"error":"cycle: build, deploy, test"}', 5, false, true, 5),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_devf_312'), 'Jobs listed out of order, ties broken by input order and by needs order', '{"jobs":[{"name":"deploy","needs":["build-arm","build-amd"],"minutes":2,"result":"success"},{"name":"build-amd","needs":["test"],"minutes":4,"result":"success"},{"name":"build-arm","needs":["test"],"minutes":4,"result":"success"},{"name":"test","needs":[],"minutes":3,"result":"success"},{"name":"notify","needs":["test"],"minutes":6,"result":"failure"}]}', '{"jobs":[{"name":"deploy","status":"success","start":7,"end":9},{"name":"build-amd","status":"success","start":3,"end":7},{"name":"build-arm","status":"success","start":3,"end":7},{"name":"test","status":"success","start":0,"end":3},{"name":"notify","status":"failure","start":3,"end":9}],"wall_minutes":9,"critical_path":["test","build-arm","deploy"]}', 5, false, true, 6);
