INSERT INTO challenge.challenge_test_cases (challenge_id, name, input_data, expected_output, score, is_sample, is_hidden, sort_order)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_devf_332'), 'A healthy canary passes 5%, 25% and 50% and is promoted', '{"config":{"max_error_rate_delta":0.5,"max_p95_increase_pct":20,"min_requests":200},"steps":[{"weight":5,"baseline":{"requests":19000,"errors":76,"p95_ms":220},"canary":{"requests":1000,"errors":5,"p95_ms":228}},{"weight":25,"baseline":{"requests":15000,"errors":63,"p95_ms":225},"canary":{"requests":5000,"errors":24,"p95_ms":240}},{"weight":50,"baseline":{"requests":10000,"errors":41,"p95_ms":223},"canary":{"requests":10000,"errors":45,"p95_ms":231}}]}', '{"decision":"PROMOTE","at_weight":null,"reason":"all 3 steps passed","checked":[{"weight":5,"result":"pass"},{"weight":25,"result":"pass"},{"weight":50,"result":"pass"}]}', 5, true, false, 1),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_devf_332'), 'The incident: 2.40% errors on the 10% canary vs 0.40% must roll back at once', '{"config":{"max_error_rate_delta":0.5,"max_p95_increase_pct":20,"min_requests":200},"steps":[{"weight":10,"baseline":{"requests":9000,"errors":36,"p95_ms":220},"canary":{"requests":1000,"errors":24,"p95_ms":230}},{"weight":50,"baseline":{"requests":10000,"errors":40,"p95_ms":220},"canary":{"requests":10000,"errors":42,"p95_ms":225}}]}', '{"decision":"ROLLBACK","at_weight":10,"reason":"error rate 2.40% vs baseline 0.40% (+2.00 pp > 0.50 pp)","checked":[{"weight":10,"result":"rollback"}]}', 5, true, false, 2),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_devf_332'), 'Only 120 canary requests at 5%: HOLD instead of trusting a lucky sample', '{"config":{"max_error_rate_delta":0.5,"max_p95_increase_pct":20,"min_requests":200},"steps":[{"weight":5,"baseline":{"requests":19000,"errors":57,"p95_ms":210},"canary":{"requests":120,"errors":0,"p95_ms":205}},{"weight":25,"baseline":{"requests":15000,"errors":45,"p95_ms":212},"canary":{"requests":5000,"errors":15,"p95_ms":215}}]}', '{"decision":"HOLD","at_weight":5,"reason":"only 120 canary requests at 5% (need 200)","checked":[{"weight":5,"result":"hold"}]}', 5, true, false, 3),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_devf_332'), 'A p95 regression at 50% with a normal error rate rolls back on latency', '{"config":{"max_error_rate_delta":0.5,"max_p95_increase_pct":20,"min_requests":200},"steps":[{"weight":5,"baseline":{"requests":19000,"errors":57,"p95_ms":228},"canary":{"requests":1000,"errors":3,"p95_ms":236}},{"weight":25,"baseline":{"requests":15000,"errors":45,"p95_ms":229},"canary":{"requests":5000,"errors":16,"p95_ms":270}},{"weight":50,"baseline":{"requests":10000,"errors":30,"p95_ms":230},"canary":{"requests":10000,"errors":35,"p95_ms":410}}]}', '{"decision":"ROLLBACK","at_weight":50,"reason":"p95 410 ms is more than 20% above baseline 230 ms","checked":[{"weight":5,"result":"pass"},{"weight":25,"result":"pass"},{"weight":50,"result":"rollback"}]}', 5, true, false, 4),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_devf_332'), 'Fewer errors than baseline in raw count but a higher rate: roll back at 25%', '{"config":{"max_error_rate_delta":0.25,"max_p95_increase_pct":20,"min_requests":200},"steps":[{"weight":5,"baseline":{"requests":19000,"errors":38,"p95_ms":200},"canary":{"requests":1000,"errors":2,"p95_ms":205}},{"weight":25,"baseline":{"requests":15000,"errors":30,"p95_ms":200},"canary":{"requests":5000,"errors":25,"p95_ms":210}},{"weight":50,"baseline":{"requests":10000,"errors":20,"p95_ms":200},"canary":{"requests":10000,"errors":20,"p95_ms":205}}]}', '{"decision":"ROLLBACK","at_weight":25,"reason":"error rate 0.50% vs baseline 0.20% (+0.30 pp > 0.25 pp)","checked":[{"weight":5,"result":"pass"},{"weight":25,"result":"rollback"}]}', 5, false, true, 5),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_devf_332'), 'Limits are inclusive at 5%, a bad 25% step stops it although 50% looks fine', '{"config":{"max_error_rate_delta":0.5,"max_p95_increase_pct":20,"min_requests":200},"steps":[{"weight":5,"baseline":{"requests":19000,"errors":57,"p95_ms":250},"canary":{"requests":200,"errors":0,"p95_ms":300}},{"weight":25,"baseline":{"requests":15000,"errors":45,"p95_ms":230},"canary":{"requests":5000,"errors":60,"p95_ms":240}},{"weight":50,"baseline":{"requests":10000,"errors":30,"p95_ms":230},"canary":{"requests":10000,"errors":31,"p95_ms":235}}]}', '{"decision":"ROLLBACK","at_weight":25,"reason":"error rate 1.20% vs baseline 0.30% (+0.90 pp > 0.50 pp)","checked":[{"weight":5,"result":"pass"},{"weight":25,"result":"rollback"}]}', 5, false, true, 6);
