-- challenge chal_quiz_devf_421 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_devf_421', (SELECT id FROM catalog.course WHERE public_id = 'devops-foundations-ci-containers'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'devops-foundations-ci-containers') AND order_index = 4 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-devf-4-2' AND is_deleted = false LIMIT 1), 'alerting-symptoms-and-ratios-quiz', 'Which alerts should page, and what the error ratio really says', 'Decide which alerts deserve a 3am page, then compute what an error-ratio alert really returns when one small route is failing.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_devf_421'), 'Rice Rocket''s on-call rule: a page must be urgent, actionable and about something users feel right now. Which of these alerts should page the on-call engineer at 3am? (Select all that apply.)', 'multiple_choice'::question_type, 'Checkout 5xx ratio above 2% for 5 minutes is a symptom users feel right now (failed orders), it is urgent and someone can act on it: page. A fast error-budget burn (14.4x over both the last 1 hour and the last 5 minutes) means 2% of the whole 30-day budget is gone in an hour and the outage is still happening: page. CPU above 80% on one node is a cause, not a symptom: if users are fine it is not urgent, and if they are not, a symptom alert already fired; at most a ticket or a dashboard. A backup that finished but ran slow is real and worth a look, but nothing is broken for users tonight: open a ticket for working hours. One pod restart that Kubernetes already fixed needs no human at all; a rising restart count belongs on a dashboard or in a ticket.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_devf_421') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('Checkout 5xx ratio above 2% for 5 minutes (route=/checkout)', true),
        ('Checkout error budget burning at 14.4x over both the last 1h and the last 5m', true),
        ('CPU above 80% on node api-3', false),
        ('The nightly database backup finished, but took 3 hours instead of the usual 1', false),
        ('Pod dispatch-7f9c restarted once and is healthy again', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_devf_421'), 'During the outage, the last 5 minutes of traffic looked like this:

  route       requests   5xx
  /menu         9000       0
  /search       2400       6
  /checkout      600     150

The only error alert was:

  expr: sum(rate(http_requests_total{code=~"5.."}[5m])) / sum(rate(http_requests_total[5m])) > 0.05
  for: 5m

What does the expression return, and does the alert fire?', 'single_choice'::question_type, 'The expression divides the total 5xx count by the total request count: 156 / 12000 = 0.013, about 1.3%, which is below 0.05, so the alert never fires while a quarter of all checkouts fail. Quiet traffic on /menu dilutes the busy failure on the small but important route. Adding by (route) to both sums keeps one ratio per route, and /checkout is 150 / 600 = 25%, far above 5%. 25% is the /checkout ratio, not what the expression returns. About 8.4% is the average of the three per-route ratios (0%, 0.25%, 25%): an average of ratios gives a tiny route the same weight as a big one, and it is not what sum()/sum() computes either. 5% is only the threshold, and for: 5m does not change the value, only how long it must stay above the threshold.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_devf_421') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('About 25%: it fires, because /checkout is far above 5%', false),
        ('About 8.4%: it fires, because the average error ratio of the routes is above 5%', false),
        ('About 1.3%: it never fires; with sum by (route) the /checkout ratio would be 25%', true),
        ('Exactly 5%: it stays pending forever because of for: 5m', false)
    ) AS o(option_text, is_correct);

-- challenge chal_fix_devf_422 (fix_bug)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_fix_devf_422', (SELECT id FROM catalog.course WHERE public_id = 'devops-foundations-ci-containers'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'devops-foundations-ci-containers') AND order_index = 4 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-devf-4-2' AND is_deleted = false LIMIT 1), 'fix-flapping-alert-evaluator', 'Stop the CPU alert from paging every few minutes', 'evaluate(rule, series) replays one metric series (one value per minute) through an alert rule and lists the pages it would send. The on-call review uses it to tune rules, but it has the same bugs as last night''s alert: a pending alert is never dropped when the value dips back under the threshold, so short spikes add up and fire, and a firing alert resolves the moment the value is not above the threshold, so a metric hovering around 80 pages again and again. Fix it so the replay follows the rules in the docstring: fire only after the condition has been true for for_minutes minutes in a row (starting again from zero after any false minute), and resolve only when the value drops below clear_below. The runner at the bottom (do not change it) prints the alerts with fired_at and resolved_at and the number of pages.', 'open', 'medium'::difficulty_question, 'fix_bug', 20, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
