VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_fix_devf_422'), 'Night CPU from the incident: for 5m and clear below 70 turn the flapping into one page', '{"rule":{"threshold":80,"for_minutes":5,"clear_below":70},"series":[[0,72],[1,79],[2,83],[3,78],[4,81],[5,79],[6,84],[7,77],[8,82],[9,80],[10,86],[11,88],[12,91],[13,93],[14,90],[15,87],[16,84],[17,79],[18,76],[19,81],[20,74],[21,68],[22,66],[23,71],[24,82],[25,79],[26,73],[27,69],[28,64],[29,62]]}', '{"alerts":[{"fired_at":15,"resolved_at":21}],"pages":1}', 4, true, false, 1),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_fix_devf_422'), 'Spikes shorter than for_minutes never page, even when they keep coming back', '{"rule":{"threshold":80,"for_minutes":3,"clear_below":70},"series":[[120,75],[121,85],[122,88],[123,79],[124,86],[125,90],[126,78],[127,91],[128,84],[129,80],[130,83],[131,87],[132,76]]}', '{"alerts":[],"pages":0}', 4, true, false, 2),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_fix_devf_422'), 'for_minutes 0 pages at once; a value between clear_below and threshold keeps it firing', '{"rule":{"threshold":90,"for_minutes":0,"clear_below":75},"series":[[0,70],[1,95],[2,88],[3,92],[4,80],[5,74],[6,60]]}', '{"alerts":[{"fired_at":1,"resolved_at":5}],"pages":1}', 4, true, false, 3),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_fix_devf_422'), 'Exactly threshold is not above it, exactly clear_below does not resolve, still firing at the end', '{"rule":{"threshold":80,"for_minutes":2,"clear_below":70},"series":[[300,80],[301,81],[302,85],[303,90],[304,70],[305,72],[306,70]]}', '{"alerts":[{"fired_at":303,"resolved_at":null}],"pages":1}', 4, false, true, 4),
